 "content": "def transform(grid):
    """Zero the two rows and columns marked by a 2x2 zero block, preserving 2s."""
    h, w = len(grid), len(grid[0])
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        return [row[:] for row in grid]
